/* GENERATED by gen_hcon_vault.py -- models are generated.
   SAT_CLAIM_ASSESSMENT_SUMMARY
   anchor      : HUB_CLAIM   (kind: hub, origin: map.anchor)
   track       : ratified
   history     : SCD2
   feeders     : 2 emitted of 2 (one per source view AND run)
   runs        : 1 -- opus_health_legacy_v4
   payload     : 4 attribute(s), NULL-PADDED TO THE SATELLITE
   grain       : ONE ROW PER HUB_CLAIM_HK
   hashdiff    : SAT_CLAIM_ASSESSMENT_SUMMARY_HASHDIFF (builder decision BD1), GUARDED against an all-null input (s5.5):
                 without the guard every all-null row hashes to ONE value and the
                 satellite collapses to one row, which looks like change detection.
   CROSS-RUN RECONCILIATION, DECLARED (carve-out ratified by the mapping counterparty):
   this satellite's anchor is one of the shared objects written by BOTH runs, whose two
   identifier registries are UNRECONCILED. The declared source precedence below is a VALUE
   CHOICE APPLIED TO ROWS THAT MAY REPRESENT TWO UNRECONCILED POPULATIONS -- two writers may
   be describing one entity, or two different parties colliding in one key space, and which
   it is cannot be settled from the map, the model or the SQL.
   WHY THE SCOPE IS EVERY SHARED OBJECT AND NOT A LOW-OVERLAP SUBSET: a hub-level
   business-key-column overlap cannot see the hazard at any threshold. HUB_PARTY's overlap
   of three is IMD_CODE, PART_ID and RM_CODE, all intermediary-side; on the member/customer
   population the overlap is ZERO. The figure is unstable too -- collapsing underscores moves
   it from three to five.
   WHY DECLARE RATHER THAN REFUSE: the choice is made on ASYMMETRY. A DECLARED CONFLICT IS
   RECOVERABLE; A WRONG MERGE IS NOT, AFTER LOAD. That is the justification, not a
   preference.
   The subordinate writer and its registry are NAMED below so the loss is COUNTABLE.
   A load-time assertion in models/assertions/ counts the hash keys actually written by both
   runs. Until it runs, whether the precedence EVER fires is UNKNOWN, not zero.
   INTRA-RUN FAN-IN, 2 attribute/run pair(s) with more than one writer, of
   which 2 are genuinely ARBITRARY. WITHIN one run several source views
   write the same attribute and the map declares NO precedence among them,
   so max() picks arbitrarily -- BUT ONLY AMONG UNDISCRIMINATED WRITERS. A
   writer carrying a resolved `instance` or a declared `redundant_of` is
   SEPARATED, not competing: a nominee's name and a policyholder's name on
   one satellite are DIFFERENT ROWS. BOTH SCOPES are quoted below because a
   bare writer count overstates the arbitrariness -- on PARTY_FULL_NAME it
   overstates it nearly fivefold.
   DECLARED, NOT RESOLVED: choosing among same-run writers would invent an
   authority the map does not provide. NO CROSS-RUN DECISION REACHES THIS.
     ADMISSIBLE_LOSS_AMOUNT                 opus_health_legacy_v4  2 writer(s), of which 2 UNDISCRIMINATED (0 separated by a resolved instance, 0 by redundant_of)  [CROSS-TABLE: check_collapse groups on (table, satellite, attribute, instance, child_key) and CANNOT see this]
     TOTAL_DEDUCTION_AMOUNT                 opus_health_legacy_v4  2 writer(s), of which 2 UNDISCRIMINATED (0 separated by a resolved instance, 0 by redundant_of)  [CROSS-TABLE: check_collapse groups on (table, satellite, attribute, instance, child_key) and CANNOT see this]
   A load-time assertion in models/assertions/ counts the DISTINCT
   values the undiscriminated writers actually supply per key. Until it
   runs, whether they ever disagree is UNKNOWN, not zero.
*/

with feeders as (
    select
        md5(upper('HUB_CLAIM|' || (HUB_CLAIM_BK__CLAIM_NO))) as HUB_CLAIM_HK
        , TOTAL_ALLOWED_AMOUNT as ADMISSIBLE_LOSS_AMOUNT
        , DEDUCTION_AMOUNT as TOTAL_DEDUCTION_AMOUNT
        , cast(null as varchar) as DEDUCTIBLE_APPLIED
        , cast(null as varchar) as ASSESSMENT_DATE
        , 'BJAZ_REMEDINET_CLAIM_DETAILS' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_remedinet_claim_details') }}
    where (nullif(trim(CLAIM_NO),'')) is not null
    union all
    select
        md5(upper('HUB_CLAIM|' || (HUB_CLAIM_BK__BJAZ_CLAIM_ID))) as HUB_CLAIM_HK
        , RECOMMEND_AMOUNT as ADMISSIBLE_LOSS_AMOUNT
        , DEDUCTED_AMOUNT as TOTAL_DEDUCTION_AMOUNT
        , COMPULSARY_DEDUCTION as DEDUCTIBLE_APPLIED
        , RECOMMEND_ON as ASSESSMENT_DATE
        , 'BJAZ_TPA_CLAIM_DETAILS_WS' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_tpa_claim_details_ws') }}
    where (nullif(trim(BJAZ_CLAIM_ID),'')) is not null
),

resolved as (
    select
        HUB_CLAIM_HK,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then ADMISSIBLE_LOSS_AMOUNT end) as ADMISSIBLE_LOSS_AMOUNT,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then TOTAL_DEDUCTION_AMOUNT end) as TOTAL_DEDUCTION_AMOUNT,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then DEDUCTIBLE_APPLIED end) as DEDUCTIBLE_APPLIED,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then ASSESSMENT_DATE end) as ASSESSMENT_DATE,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_CLAIM_HK
),

hashed as (
    select
        *,
        case when ADMISSIBLE_LOSS_AMOUNT is not null or TOTAL_DEDUCTION_AMOUNT is not null or DEDUCTIBLE_APPLIED is not null or ASSESSMENT_DATE is not null
                     then md5(upper(coalesce(cast(ADMISSIBLE_LOSS_AMOUNT as varchar), '') || '|' || coalesce(cast(TOTAL_DEDUCTION_AMOUNT as varchar), '') || '|' || coalesce(cast(DEDUCTIBLE_APPLIED as varchar), '') || '|' || coalesce(cast(ASSESSMENT_DATE as varchar), '')))
                end as SAT_CLAIM_ASSESSMENT_SUMMARY_HASHDIFF
    from resolved
)

select * from hashed
where HUB_CLAIM_HK is not null
  and SAT_CLAIM_ASSESSMENT_SUMMARY_HASHDIFF is not null
